def normalize_metric_payload(payload):
    payload['start_time'] = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    payload['end_time'] = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    return payload

from typing import Any, Dict


def normalize_metric_response(response: Dict[str, Any]) -> Dict[str, Any]:
    normalized = {}
    for key, value in response.items():
        if isinstance(value, list):
            normalized[key] = [normalize_metric_point(point) for point in value]
        else:
            normalized[key] = value
    return normalized


def normalize_metric_point(point: Dict[str, Any]) -> Dict[str, Any]:
    return {'timestamp': point['timestamp'].timestamp(), 'value': float(point['value'])}

from google.cloud import monitoring_v3


def summarize_metric_trends(payload):
    client = monitoring_v3.MetricServiceClient()
    name = f'projects/{payload['project_id']}/metricDescriptors/{payload['metric_type']}'
    result = client.list_time_series(name, filter=payload['filter'], interval=payload['interval'])
    points = [{'timestamp': point.interval.end_time.seconds, 'value': point.value.double_value}
               for point in result]
    return {'points': sorted(points, key=lambda point: point['timestamp'])}

import re


def check_metric_annotation_safety(annotation):
    unsafe_patterns = [r'\bunsafe\b', r'\bmalicious\b']
    for pattern in unsafe_patterns:
        if re.search(pattern, annotation, re.IGNORECASE):
            return False
    return True

